import{z as A,x as s,o as t,c as p,q as r,j as B,D as e,d as n,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"latch crabbing","description":"","frontmatter":{"title":"latch crabbing","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/latch-crabbing.md","filePath":"cs/latch-crabbing.md","lastUpdated":1791063341000}'),d={name:"cs/latch-crabbing.md"};function c(h,a,b,D,m,C){const l=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="latch-crabbing" tabindex="-1">latch crabbing <a class="header-anchor" href="#latch-crabbing" aria-label="Permalink to &quot;latch crabbing&quot;">​</a></h1><div class="epigraph"><p>从根到叶蟹行：先闩孩子再放父亲，使分裂不会在未保护的路径上发生；读可乐观，写才耦合。</p><footer>—— 据 Lehman and Yao, Efficient Locking for Concurrent Operations on B-Trees, TODS 1981；Mohan 与 ARIES/IM；Gray</footer></div><p><a href="/cs/pin-latch">上一课</a>区分 pin 与 latch。本课不重定义写闩。缺口是 B+ 遍历：若从根到叶一路持有所有闩，并发插入几乎停。crabbing（蟹行 / latch coupling）：持父闩，闩住孩子，立刻放父，使窗口里最多两层。分裂时要再向上，协议更严。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干 B+ 分裂课讲结构，几乎单线程。并发：读者看内部节点指针时，写者可能分裂把键挪走。安全：写遍历在可能分裂的节点上保持闩直到确定孩子「安全」（有空槽）才放父；不安全则保持以便回头分裂。读：可在每层放闩后乐观继续，若发现链接不一致则重试——Lehman-Yao 的右链指针让读不挡写。</p><p>缺口是<strong>协议</strong>，不是 B+ 阶数。与事务行锁：行锁在叶记录上，latch 在页上，先 latch 后 lock 或按引擎规定的顺序，避免两层死锁。</p><p><span class="marginnote">直觉类比：「蟹行」这名字来自螃蟹横着走——先闩住孩子（迈出后脚），再放掉父亲（收回前脚），树上任意时刻至少有一只「脚」踩在节点上，走过的路径永远不失去保护。若一口气闩住从根到叶整条链，其他读者就得在根上排队。</span></p><p><span class="marginnote">Lehman and Yao TODS 1981，B-link 树。ARIES/IM 讨论索引并发与恢复。本课用 crabbing 统称耦合闩锁，不把每篇变体的位图抄进来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：根闩 → 找孩子 → 闩孩子 → 放根 → … → 叶。若节点带删除或分裂标记，按右链走或重从根。写：类似，但在满节点上不放祖先，或用「安全节点」截止。SMO（结构修改）要记日志，恢复与 ARIES 索引一致。</p><p>Bw-tree 下一课用无闩+映射表，是另一族；本课先钉经典页闩。</p>',11)),(t(),B(o,null,{default:e(()=>[i(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%97%A9%E4%BD%8F%E7%88%B6%22%5D%20--%3E%20C%5B%22%E9%97%A9%E4%BD%8F%E5%AD%90%22%5D%0A%20%20C%20--%3E%20RP%5B%22%E6%94%BE%E7%88%B6%22%5D%0A%20%20RP%20--%3E%20NXT%5B%22%E5%AD%90%E6%88%90%E4%B8%BA%E6%96%B0%E7%88%B6%22%5D%0A%20%20FULL%5B%22%E5%AD%90%E6%BB%A1%E4%B8%94%E8%A6%81%E5%86%99%22%5D%20--%3E%20KEEP%5B%22%E4%B8%8D%E6%94%BE%E7%A5%96%E5%85%88%E7%9B%B4%E5%88%B0%E5%88%86%E8%A3%82%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"pin 与 latch 一起：闩住的页必 pin。蟹行失败（要再向上）时可能重新从根，避免持有长链。高并发下根是热点：根几乎不分裂后可变只读闩优化，或把根钉死在池里。",-1)),a[5]||(a[5]=E("p",null,"性能：读蟹行短，写 SMO 长。与 2Q 互动：内部节点应常驻，替换策略应偏爱高层页。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：扇出 100 的 B+ 树存 100 万行大约只要 3 层内部节点加 1 层叶。悲观做法从根闩到叶要同时持有约 4 个页闩；蟹行读任意时刻最多闩 2 个页，根上的闩立刻释放——千级并发的读者在根处的排队就这样消失。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"常见误区：初学者容易以为读路径也要像写一样处处严防。实际上读可以乐观：只闩当前节点、看一眼有无分裂或删除标记，干净就继续；发现不一致才沿 B-link 的右链横走或重从根。闩保护的是「页内指针别被改到一半」，它管不了幻读——那是事务级谓词锁的事。")],-1)),(t(),B(o,null,{default:e(()=>[i(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E4%B9%90%E8%A7%82%E8%AF%BB%3A%20%E5%8F%AA%E9%97%A9%E5%BD%93%E5%89%8D%E8%8A%82%E7%82%B9%22%5D%20--%3E%20CHK%7B%22%E6%9C%89%E5%88%86%E8%A3%82%E6%88%96%E5%88%A0%E9%99%A4%E6%A0%87%E8%AE%B0%3F%22%7D%0A%20%20CHK%20--%3E%7C%22%E5%B9%B2%E5%87%80%22%7C%20OK%5B%22%E5%8F%96%E5%AD%A9%E5%AD%90%E6%8C%87%E9%92%88%2C%20%E7%AB%8B%E5%88%BB%E6%94%BE%E9%97%A9%22%5D%0A%20%20OK%20--%3E%20NXT%5B%22%E5%9C%A8%E4%B8%8B%E4%B8%80%E5%B1%82%E9%87%8D%E5%A4%8D%E5%90%8C%E6%B3%95%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%9C%89%E6%A0%87%E8%AE%B0%22%7C%20RL%5B%22%E6%94%BE%E9%97%A9%2C%20%E6%B2%BF%E5%8F%B3%E9%93%BE%E6%A8%AA%E8%B5%B0%E5%88%B0%E6%AD%A3%E7%A1%AE%E5%85%84%E5%BC%9F%22%5D%0A%20%20RL%20--%3E%20Q2%7B%22%E7%9B%AE%E6%A0%87%E8%8C%83%E5%9B%B4%E5%B7%B2%E8%A6%86%E7%9B%96%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20LK%5B%22%E9%87%8D%E6%96%B0%E9%97%A9%E4%BD%8F%E7%9B%AE%E6%A0%87%E8%8A%82%E7%82%B9%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20RE%5B%22%E4%BB%8E%E6%A0%B9%E9%87%8D%E6%9D%A5%22%5D%0A%20%20LK%20--%3E%20NXT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=r('<p>这张图回答的问题：乐观读遇到并发分裂时如何自救。与上图写路径「不放祖先直到安全」互补——读侧代价极低、错了就横走或重试，写侧则必须在可能分裂的节点上耦合祖先，两个协议合起来才是不挡读的 B+ 并发。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Bw-tree 的 delta 记录。也不把间隙锁当 latch。间隙锁是事务级，后课。</p><p>后课默认：B+ 并发读蟹行或 B-link；写在不安全节点上耦合。Bw-tree：用映射表与 delta 减少写闩。</p><p>蟹行保护的是页指针正确，不是幻读；幻读要谓词锁或间隙锁。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>蟹行同时最多闩两层（读），写在可能 SMO 时延长。</li><li>B-link 右链让读乐观。</li><li>Bw-tree 下一课：无传统写闩的映射+delta。</li><li>出处：Lehman and Yao 1981；ARIES/IM；Gray and Reuter。</li></ul>',7))])}const g=A(d,[["render",c]]);export{f as __pageData,g as default};
